// Test save positions (tests/fixtures/saves, generated by `npm run fixtures`): `?fixture=<name>` boots
// a dev build straight into one of them. Imported only behind `import.meta.env.DEV` (main.ts), so the
// production build contains neither this module nor the save files.
import { loadSave } from '../sim/save/load';
import { restoreSimulation } from '../sim/save/serialize';
import type { Simulation } from '../sim/Simulation';

declare global {
  interface Window {
    /** Dev only: the fixture the page booted into, or `error: …` when it could not be loaded. */
    __cinderFixture?: string;
  }
}

const DIR = '/tests/fixtures/saves/';
const FILES = import.meta.glob('/tests/fixtures/saves/*.json', { query: '?raw', import: 'default' }) as Record<string, () => Promise<string>>;

/** Names of the available fixtures (file names without `.json`). */
export const fixtureNames = (): string[] =>
  Object.keys(FILES)
    .map((path) => path.slice(DIR.length, -'.json'.length))
    .sort();

/** The raw save envelope of a fixture (JSON text), or null when there is no such fixture. */
export async function fixtureText(name: string): Promise<string | null> {
  const file = FILES[`${DIR}${name}.json`];
  return file ? file() : null;
}

/** A simulation restored from a fixture through the normal load path (migrate + validate). */
export async function loadFixtureSim(name: string): Promise<Simulation> {
  const text = await fixtureText(name);
  if (text === null) throw new Error(`Unknown fixture "${name}" – available: ${fixtureNames().join(', ')}`);
  const result = loadSave(JSON.parse(text));
  if (!result.ok) throw new Error(`Fixture "${name}" does not load: ${result.error} ${result.details.join('; ')}`);
  return restoreSimulation(result.save);
}
